package Dialogos;
import Configuracion.conexion;
import java.awt.*;
import java.math.*;
import java.sql.*;
import java.util.*;
import javax.swing.*;

/** Edición segura: no modifica existencias ni código histórico. */
public class DialogoEditarArticulo extends JDialog {
 private final int id;private boolean guardado;
 private final JTextField codigo=new JTextField(),barra=new JTextField(),interno=new JTextField(),nombre=new JTextField(),descripcion=new JTextField(),ubicacion=new JTextField(),costo=new JTextField(),precio=new JTextField(),minimo=new JTextField(),factor=new JTextField();
 private final JComboBox<Item> categoria=new JComboBox<>(),rubro=new JComboBox<>(),marca=new JComboBox<>(),iva=new JComboBox<>(),compra=new JComboBox<>(),venta=new JComboBox<>();
 private final JCheckBox activo=new JCheckBox("Activo"),controla=new JCheckBox("Controla stock"),sinStock=new JCheckBox("Permite venta sin stock"),pesable=new JCheckBox("Pesable"),descuento=new JCheckBox("Permite descuentos");
 private static class Item{final Integer id;final String nombre;Item(Integer i,String n){id=i;nombre=n;}public String toString(){return nombre;}}
 public DialogoEditarArticulo(Window owner,int id){super(owner,"Editar artículo · Serena Soft",ModalityType.APPLICATION_MODAL);this.id=id;setLayout(new BorderLayout(8,8));getContentPane().setBackground(new Color(244,248,253));
 JLabel titulo=new JLabel("  EDITAR ARTÍCULO · SERENA SOFT");titulo.setOpaque(true);titulo.setBackground(new Color(20,57,117));titulo.setForeground(Color.WHITE);titulo.setFont(new Font("Segoe UI",Font.BOLD,21));titulo.setPreferredSize(new Dimension(0,62));add(titulo,BorderLayout.NORTH);
 JPanel grid=new JPanel(new GridLayout(0,2,15,12));grid.setBackground(Color.WHITE);grid.setBorder(BorderFactory.createEmptyBorder(18,22,18,22));
 codigo.setEditable(false);codigo.setBackground(new Color(225,235,249));
 campo(grid,"Código Serena Soft (no editable)",codigo);campo(grid,"Código de barras",barra);campo(grid,"Código interno",interno);campo(grid,"Nombre *",nombre);campo(grid,"Descripción",descripcion);campo(grid,"Ubicación",ubicacion);campo(grid,"Rubro",rubro);campo(grid,"Categoría",categoria);campo(grid,"Marca",marca);campo(grid,"IVA",iva);campo(grid,"Unidad de compra",compra);campo(grid,"Unidad de venta",venta);campo(grid,"Factor de conversión",factor);campo(grid,"Costo unitario ($)",costo);campo(grid,"Precio de venta ($)",precio);campo(grid,"Stock mínimo",minimo);
 JPanel checks=new JPanel(new FlowLayout(FlowLayout.LEFT,14,9));checks.setBackground(Color.WHITE);for(JCheckBox c:new JCheckBox[]{activo,controla,sinStock,pesable,descuento})checks.add(c);
 JPanel centro=new JPanel(new BorderLayout());centro.add(grid,BorderLayout.CENTER);centro.add(checks,BorderLayout.SOUTH);JScrollPane sc=new JScrollPane(centro);sc.getVerticalScrollBar().setUnitIncrement(18);add(sc,BorderLayout.CENTER);
 JPanel pie=new JPanel(new FlowLayout(FlowLayout.RIGHT,12,12));pie.setBackground(Color.WHITE);JButton cancelar=new JButton("CANCELAR"),guardar=new JButton("GUARDAR CAMBIOS");guardar.setBackground(new Color(22,132,91));guardar.setForeground(Color.WHITE);guardar.setFont(new Font("Segoe UI",Font.BOLD,13));pie.add(cancelar);pie.add(guardar);add(pie,BorderLayout.SOUTH);cancelar.addActionListener(e->dispose());guardar.addActionListener(e->guardar());getRootPane().setDefaultButton(guardar);
 setSize(930,Math.min(730,Toolkit.getDefaultToolkit().getScreenSize().height-90));setLocationRelativeTo(owner);try{cargar();}catch(SQLException ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Error",JOptionPane.ERROR_MESSAGE);guardar.setEnabled(false);}}
 private static void campo(JPanel p,String texto,JComponent c){JPanel f=new JPanel(new BorderLayout(0,4));f.setOpaque(false);JLabel l=new JLabel(texto);l.setForeground(new Color(20,57,117));l.setFont(new Font("Segoe UI",Font.BOLD,12));f.add(l,BorderLayout.NORTH);c.setPreferredSize(new Dimension(200,34));f.add(c,BorderLayout.CENTER);p.add(f);}
 private void cargarCombo(Connection cn,JComboBox<Item> c,String sql)throws SQLException{c.addItem(new Item(null,"Sin asignar"));try(PreparedStatement ps=cn.prepareStatement(sql);ResultSet rs=ps.executeQuery()){while(rs.next())c.addItem(new Item(rs.getInt(1),rs.getString(2)));}}
 private static void elegir(JComboBox<Item> c,int id){for(int i=0;i<c.getItemCount();i++)if(Objects.equals(c.getItemAt(i).id,id==0?null:id)){c.setSelectedIndex(i);return;}}
 private static Integer seleccionado(JComboBox<Item> c){Item i=(Item)c.getSelectedItem();return i==null?null:i.id;}
 private void cargar()throws SQLException{try(Connection cn=conexion.getConexion()){
 cargarCombo(cn,rubro,"SELECT id_rubro,nombre FROM rubro ORDER BY nombre");cargarCombo(cn,categoria,"SELECT id_categoria,nombre FROM categoria ORDER BY nombre");cargarCombo(cn,marca,"SELECT id_marca,nombre FROM marca ORDER BY nombre");cargarCombo(cn,iva,"SELECT id_iva,nombre FROM tipo_iva ORDER BY nombre");cargarCombo(cn,compra,"SELECT id_unidad,nombre FROM unidad_medida ORDER BY nombre");cargarCombo(cn,venta,"SELECT id_unidad,nombre FROM unidad_medida ORDER BY nombre");
 try(PreparedStatement ps=cn.prepareStatement("SELECT * FROM producto WHERE id_producto=?")){ps.setInt(1,id);try(ResultSet r=ps.executeQuery()){if(!r.next())throw new SQLException("El artículo no existe.");codigo.setText(r.getString("codigo"));barra.setText(r.getString("codigo_barra"));interno.setText(r.getString("codigo_interno"));nombre.setText(r.getString("nombre"));descripcion.setText(r.getString("descripcion"));ubicacion.setText(r.getString("ubicacion"));costo.setText(r.getBigDecimal("precio_compra").toPlainString());precio.setText(r.getBigDecimal("precio_venta").toPlainString());minimo.setText(r.getBigDecimal("stock_minimo").toPlainString());factor.setText(r.getBigDecimal("factor_conversion").toPlainString());elegir(rubro,r.getInt("id_rubro"));elegir(categoria,r.getInt("id_categoria"));elegir(marca,r.getInt("id_marca"));elegir(iva,r.getInt("id_iva"));elegir(compra,r.getInt("id_unidad_compra"));elegir(venta,r.getInt("id_unidad_venta"));activo.setSelected(r.getBoolean("activo"));controla.setSelected(r.getBoolean("controla_stock"));sinStock.setSelected(r.getBoolean("permite_venta_sin_stock"));pesable.setSelected(r.getBoolean("es_pesable"));descuento.setSelected(r.getBoolean("permite_descuento"));}}}}
 private static void nullable(PreparedStatement p,int n,Integer id)throws SQLException{if(id==null)p.setNull(n,Types.INTEGER);else p.setInt(n,id);}
 private static void texto(PreparedStatement p,int n,String s)throws SQLException{if(s==null||s.isBlank())p.setNull(n,Types.VARCHAR);else p.setString(n,s.trim());}
 private void guardar(){try{
 if(nombre.getText().isBlank())throw new Exception("El nombre es obligatorio.");BigDecimal pc=new BigDecimal(costo.getText().trim().replace(',','.')),pv=new BigDecimal(precio.getText().trim().replace(',','.')),min=new BigDecimal(minimo.getText().trim().replace(',','.')),fc=new BigDecimal(factor.getText().trim().replace(',','.'));
 if(pc.signum()<0||pv.signum()<0||min.signum()<0||fc.signum()<=0)throw new Exception("Precios y stock mínimo deben ser positivos o cero; factor mayor que cero.");if(pc.scale()>2||pv.scale()>2||min.scale()>3||fc.scale()>4)throw new Exception("Revisá los decimales de importes, mínimo o factor.");
 if(seleccionado(compra)==null||seleccionado(venta)==null)throw new Exception("Seleccioná unidades de compra y venta.");
 try(Connection cn=conexion.getConexion()){cn.setAutoCommit(false);try{
 // Impedir cambiar unidades si existen movimientos/presentaciones que dependen de ellas.
 try(PreparedStatement check=cn.prepareStatement("SELECT id_unidad_compra,id_unidad_venta,factor_conversion FROM producto WHERE id_producto=? FOR UPDATE")){check.setInt(1,id);try(ResultSet r=check.executeQuery()){if(!r.next())throw new SQLException("Artículo inexistente.");boolean unidadesCambiadas=!Objects.equals(r.getInt(1),seleccionado(compra))||!Objects.equals(r.getInt(2),seleccionado(venta))||r.getBigDecimal(3).compareTo(fc)!=0;if(unidadesCambiadas){try(PreparedStatement mov=cn.prepareStatement("SELECT (SELECT COUNT(*) FROM producto_presentacion WHERE id_producto=?) + (SELECT COUNT(*) FROM stock_producto WHERE id_producto=?)")){mov.setInt(1,id);mov.setInt(2,id);try(ResultSet m=mov.executeQuery()){m.next();if(m.getLong(1)>0)throw new SQLException("Este artículo tiene presentaciones o existencias. Para proteger la conversión histórica, no se pueden cambiar sus unidades/factor desde Editar. Utilizá la gestión de presentaciones.");}}}}}
 String sql="UPDATE producto SET codigo_interno=?,codigo_barra=?,nombre=?,descripcion=?,ubicacion=?,id_rubro=?,id_categoria=?,id_marca=?,id_iva=?,id_unidad_compra=?,id_unidad_venta=?,factor_conversion=?,precio_compra=?,precio_venta=?,margen_porcentaje=?,stock_minimo=?,activo=?,controla_stock=?,permite_venta_sin_stock=?,es_pesable=?,permite_descuento=? WHERE id_producto=?";
 try(PreparedStatement p=cn.prepareStatement(sql)){texto(p,1,interno.getText());texto(p,2,barra.getText());p.setString(3,nombre.getText().trim());texto(p,4,descripcion.getText());texto(p,5,ubicacion.getText());nullable(p,6,seleccionado(rubro));nullable(p,7,seleccionado(categoria));nullable(p,8,seleccionado(marca));nullable(p,9,seleccionado(iva));nullable(p,10,seleccionado(compra));nullable(p,11,seleccionado(venta));p.setBigDecimal(12,fc);p.setBigDecimal(13,pc);p.setBigDecimal(14,pv);p.setBigDecimal(15,pc.signum()==0?BigDecimal.ZERO:pv.subtract(pc).multiply(new BigDecimal("100")).divide(pc,2,RoundingMode.HALF_UP));p.setBigDecimal(16,min);p.setBoolean(17,activo.isSelected());p.setBoolean(18,controla.isSelected());p.setBoolean(19,sinStock.isSelected());p.setBoolean(20,pesable.isSelected());p.setBoolean(21,descuento.isSelected());p.setInt(22,id);if(p.executeUpdate()!=1)throw new SQLException("No se actualizó el artículo.");}
 cn.commit();guardado=true;JOptionPane.showMessageDialog(this,"Artículo actualizado correctamente.");dispose();}catch(Exception ex){cn.rollback();throw ex;}finally{cn.setAutoCommit(true);}}
 }catch(Exception ex){JOptionPane.showMessageDialog(this,"No se pudo guardar:\n"+ex.getMessage(),"Serena Soft",JOptionPane.ERROR_MESSAGE);}}
 public boolean isGuardado(){return guardado;}
}
